import { Injectable } from '@nestjs/common';
import type {
  Customer,
  CustomerStatus,
  CustomerType,
  DataClassification,
  Document,
  DocumentCategory,
  InteractionChannel,
  LanguagePreference,
  Prisma,
  UltimateBeneficialOwner,
} from '@ibms/db';
import { PrismaService } from '../prisma/prisma.service';

export interface CreateCustomerInput {
  /** Pre-generated by CustomerService (crypto.randomUUID()) BEFORE this
   * call, so EncryptionService has a real entityId to attribute the
   * encrypt-time ENCRYPTION_KEY_USED audit rows to — the row does not exist
   * yet at the point encryption happens, so there is no id to read back
   * afterward the way most other create() calls work. */
  id: string;
  prospectId?: string;
  customerType: CustomerType;
  legalName: string;
  registrationNumber?: string;
  nationalIdEnc?: string;
  taxRegistrationNumber?: string;
  registeredAddress?: string;
  natureOfBusiness?: string;
  contactPhoneEnc?: string;
  contactEmailEnc?: string;
  languagePreference: LanguagePreference;
  preferredContactChannel?: InteractionChannel;
  ownerUserId: string;
}

export interface CustomerFilter {
  ownerUserId?: string;
  status?: CustomerStatus;
}

export interface CreateUboInput {
  /** Same pre-generated-id rationale as CreateCustomerInput.id above. */
  id: string;
  customerId: string;
  fullName: string;
  nationalIdEnc: string;
  ownershipPercent?: Prisma.Decimal;
  isAuthorizedSignatory: boolean;
  isPep: boolean;
}

export interface CreateCustomerDocumentInput {
  customerId: string;
  category: DocumentCategory;
  classification: DataClassification;
  fileName: string;
  storageRef: string;
  uploadedByUserId: string;
}

/** Process 3-4 (Customer Acquisition/Onboarding) — Customer plus its two
 * customer-scoped child collections, UBO and (customer-owned) Document. Kept
 * in one repository, same "one repository per aggregate root" shape as
 * lead.repository.ts/prospect.repository.ts, since all three tables are
 * only ever read/written together through this one onboarding flow. */
@Injectable()
export class CustomerRepository {
  constructor(private readonly prisma: PrismaService) {}

  create(input: CreateCustomerInput): Promise<Customer> {
    return this.prisma.client.customer.create({ data: input });
  }

  findById(id: string): Promise<Customer | null> {
    return this.prisma.client.customer.findUnique({ where: { id } });
  }

  findMany(filter: CustomerFilter): Promise<Customer[]> {
    return this.prisma.client.customer.findMany({
      where: { ownerUserId: filter.ownerUserId, status: filter.status },
      orderBy: { createdAt: 'desc' },
    });
  }

  /** Every ACTIVE customer — used by the recurring screening batch
   * (screening-batch.scheduler.ts) to find who a "material change" rerun
   * should cover. */
  findActive(): Promise<Customer[]> {
    return this.prisma.client.customer.findMany({
      where: { status: 'ACTIVE' },
    });
  }

  createUbo(input: CreateUboInput): Promise<UltimateBeneficialOwner> {
    return this.prisma.client.ultimateBeneficialOwner.create({
      data: input,
    });
  }

  findUbosByCustomerId(customerId: string): Promise<UltimateBeneficialOwner[]> {
    return this.prisma.client.ultimateBeneficialOwner.findMany({
      where: { customerId },
      orderBy: { createdAt: 'desc' },
    });
  }

  createDocument(input: CreateCustomerDocumentInput): Promise<Document> {
    return this.prisma.client.document.create({ data: input });
  }

  findDocumentsByCustomerId(customerId: string): Promise<Document[]> {
    return this.prisma.client.document.findMany({
      where: { customerId },
      orderBy: { createdAt: 'desc' },
    });
  }
}
